import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

@DisplayName("OrderCalculator")
class OrderCalculatorTest {

    private OrderCalculator calculator;

    @BeforeEach
    void setUp() {
        calculator = new OrderCalculator();
    }

    @AfterEach
    void tearDown() {
        calculator = null;
    }

    @Test
    @DisplayName("tinh tong don hang hop le")
    void calculatesTotalCorrectly() {
        // assertAll gom nhieu assertion trong mot test - tat ca deu duoc chay
        // va bao cao, khong dung lai o assertion loi dau tien.
        Assertions.assertAll("order total",
                () -> Assertions.assertEquals(100, calculator.total(),
                        "tong phai la 100"),
                () -> Assertions.assertTrue(calculator.isValid(),
                        "don hang phai hop le"));
    }

    @Test
    void throwsWhenQuantityNegative() {
        Assertions.assertThrows(IllegalArgumentException.class,
                () -> calculator.addItem(-1, 10));
    }

    static class OrderCalculator {
        int total() { return 100; }
        boolean isValid() { return true; }
        void addItem(int quantity, int price) {
            if (quantity < 0) throw new IllegalArgumentException("quantity < 0");
        }
    }
}

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.test.web.servlet.MockMvc;

import static org.mockito.BDDMockito.given;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

// Chi khoi tao ProductController va cac thanh phan lien quan toi MVC
// (khong nap toan bo Spring context nhu @SpringBootTest).
@WebMvcTest(ProductController.class)
class ProductControllerTest {

    @Autowired
    private MockMvc mockMvc;

    // Thay the ProductService that bang mot mock, vi @WebMvcTest khong tao bean tang service/repository.
    @MockBean
    private ProductService productService;

    @Test
    void returnsProductByIdAsJson() throws Exception {
        given(productService.findById(1L)).willReturn(new ProductDTO(1L, "Ban phim"));

        mockMvc.perform(get("/api/products/1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.name").value("Ban phim"));
    }

    interface ProductService { ProductDTO findById(Long id); }
    interface ProductController {}
    record ProductDTO(Long id, String name) {}
}

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import org.springframework.boot.test.autoconfigure.orm.jpa.TestEntityManager;

import static org.junit.jupiter.api.Assertions.assertEquals;

// Chi khoi tao lop JPA (entity, repository) voi H2 in-memory tu dong cau hinh,
// khong nap Controller/Service - nhanh hon nhieu so voi @SpringBootTest day du.
@DataJpaTest
class ProductRepositoryTest {

    @Autowired
    private TestEntityManager entityManager;

    @Autowired
    private ProductRepository productRepository;

    @Test
    void findsProductBySku() {
        Product saved = entityManager.persistAndFlush(new Product("SKU-001", "Ban phim"));

        Product found = productRepository.findBySku("SKU-001").orElseThrow();

        assertEquals(saved.getId(), found.getId());
    }

    interface ProductRepository {
        java.util.Optional<Product> findBySku(String sku);
    }

    static class Product {
        private Long id;
        private final String sku;
        private final String name;
        Product(String sku, String name) { this.sku = sku; this.name = name; }
        Long getId() { return id; }
    }
}

import io.restassured.RestAssured;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

// RANDOM_PORT: khoi dong mot server HTTP that tren cong ngau nhien,
// cho phep goi API qua HTTP client that (RestAssured) thay vi MockMvc gia lap.
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class ProductApiIntegrationTest {

    @LocalServerPort
    private int port;

    @BeforeEach
    void setUp() {
        RestAssured.port = port;
    }

    @Test
    void getProductReturnsOkStatus() {
        given()
                .when().get("/api/products/1")
                .then()
                .statusCode(200)
                .body("name", equalTo("Ban phim"));
    }
}

